<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;use Illuminate\Database\Eloquent\Relations\BelongsToMany;use Illuminate\Support\Str;
class Video extends Model{protected $fillable=['video_category_id','video_series_id','title','slug','description','provider','video_path','thumbnail_path','subtitle_path','subtitle_language','duration_seconds','episode_number','is_published','published_at'];protected function casts():array{return['is_published'=>'boolean','published_at'=>'datetime'];}public function getRouteKeyName():string{return 'slug';}public function category():BelongsTo{return $this->belongsTo(VideoCategory::class,'video_category_id');}public function series():BelongsTo{return $this->belongsTo(VideoSeries::class,'video_series_id');}public function playlists():BelongsToMany{return $this->belongsToMany(VideoPlaylist::class,'video_playlist_items')->withPivot('position');}public function publicUrl():string{return Str::startsWith($this->video_path,['http://','https://'])?$this->video_path:asset('storage/'.$this->video_path);}}
